using System.ComponentModel.DataAnnotations;

namespace sv_fa843d08d3234278a0f855c3615fa3b2.Models;

public class AppointmentStep1Model
{
    [Required(ErrorMessage = "Patient name is required.")]
    public string? PatientName { get; set; }

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Invalid email format.")]
    public string? Email { get; set; }

    [Required(ErrorMessage = "Phone number is required.")]
    public string? Phone { get; set; }

    [Required(ErrorMessage = "Insurance provider is required.")]
    public string? InsuranceProvider { get; set; }
}

public class AppointmentStep2Model
{
    [Required(ErrorMessage = "Please select a doctor.")]
    public string? Doctor { get; set; }

    [Required(ErrorMessage = "Date is required.")]
    public DateOnly? Date { get; set; }

    [Required(ErrorMessage = "Please select a time slot.")]
    public string? TimeSlot { get; set; }

    [Required(ErrorMessage = "Reason for visit is required.")]
    [MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer.")]
    public string? ReasonForVisit { get; set; }
}

namespace sv_fa843d08d3234278a0f855c3615fa3b2.Services;

public class AppointmentService
{
    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(new List<string>
        {
            "Dr. Smith",
            "Dr. Johnson",
            "Dr. Patel",
            "Dr. Williams"
        });
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateOnly date)
    {
        // Stub: return fixed slots regardless of doctor/date
        return Task.FromResult(new List<string>
        {
            "9:00 AM",
            "10:00 AM",
            "11:00 AM",
            "1:00 PM",
            "2:00 PM",
            "3:00 PM"
        });
    }

    /// <summary>
    /// Validates patient info and appointment selection against server-side business rules.
    /// Returns a dictionary of field name → error messages. Empty means valid.
    /// </summary>
    public Task<Dictionary<string, List<string>>> ValidatePatientAsync(
        string email, string insuranceProvider, string doctor, string timeSlot)
    {
        var errors = new Dictionary<string, List<string>>();

        // Outstanding balance check
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors["Email"] = ["Account has outstanding balance"];
        }

        // Self-pay restriction
        if (string.Equals(insuranceProvider, "None", StringComparison.Ordinal)
            && string.Equals(doctor, "Dr. Smith", StringComparison.Ordinal))
        {
            errors["Doctor"] = ["Selected doctor does not accept self-pay patients"];
        }

        // Race condition: slot already taken
        if (string.Equals(timeSlot, "10:00 AM", StringComparison.Ordinal))
        {
            errors["TimeSlot"] = ["This slot is no longer available"];
        }

        return Task.FromResult(errors);
    }
}

using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Forms;

namespace sv_fa843d08d3234278a0f855c3615fa3b2.Components;

public class CustomValidator : ComponentBase
{
    [CascadingParameter]
    private EditContext? EditContext { get; set; }

    private ValidationMessageStore? messageStore;

    protected override void OnInitialized()
    {
        messageStore = new ValidationMessageStore(EditContext!);
        EditContext!.OnValidationRequested += (s, e) => messageStore.Clear();
        EditContext!.OnFieldChanged += (s, e) => messageStore.Clear(e.FieldIdentifier);
    }

    public void DisplayErrors(Dictionary<string, List<string>> errors)
    {
        foreach (var (field, messages) in errors)
        {
            foreach (var message in messages)
            {
                messageStore!.Add(EditContext!.Field(field), message);
            }
        }
        EditContext!.NotifyValidationStateChanged();
    }

    public void ClearErrors()
    {
        messageStore?.Clear();
        EditContext?.NotifyValidationStateChanged();
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_fa843d08d3234278a0f855c3615fa3b2.Models
@using sv_fa843d08d3234278a0f855c3615fa3b2.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3>Book a Medical Appointment</h3>

@* ───── STEP 1: Patient Information ───── *@
<h5 class="mt-4">Step 1 — Patient Information</h5>

<EditForm Model="Step1" OnValidSubmit="HandleStep1Submit" FormName="step1">
    <DataAnnotationsValidator />

    <div class="mb-3">
        <label class="form-label">Patient Name</label>
        <InputText class="form-control" @bind-Value="Step1.PatientName" />
        <ValidationMessage For="() => Step1.PatientName" />
    </div>

    <div class="mb-3">
        <label class="form-label">Email</label>
        <InputText class="form-control" @bind-Value="Step1.Email" />
        <ValidationMessage For="() => Step1.Email" />
    </div>

    <div class="mb-3">
        <label class="form-label">Phone</label>
        <InputText class="form-control" @bind-Value="Step1.Phone" />
        <ValidationMessage For="() => Step1.Phone" />
    </div>

    <div class="mb-3">
        <label class="form-label">Insurance Provider</label>
        <InputSelect class="form-select" @bind-Value="Step1.InsuranceProvider">
            <option value="">-- Select --</option>
            <option value="Aetna">Aetna</option>
            <option value="BlueCross">BlueCross</option>
            <option value="Cigna">Cigna</option>
            <option value="UnitedHealth">UnitedHealth</option>
            <option value="None">None</option>
        </InputSelect>
        <ValidationMessage For="() => Step1.InsuranceProvider" />
    </div>

    <button type="submit" class="btn btn-primary">Next</button>
</EditForm>

@* ───── STEP 2: Appointment Details ───── *@
@if (showStep2)
{
    <hr />
    <h5 class="mt-3">Step 2 — Appointment Details</h5>

    <EditForm EditContext="step2EditContext" OnSubmit="HandleStep2Submit" FormName="step2">
        <DataAnnotationsValidator />
        <CustomValidator @ref="customValidator" />

        <div class="mb-3">
            <label class="form-label">Preferred Doctor</label>
            <InputSelect class="form-select" @bind-Value="Step2.Doctor">
                <option value="">-- Select --</option>
                @foreach (var doc in doctors)
                {
                    <option value="@doc">@doc</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Step2.Doctor" />
        </div>

        <div class="mb-3">
            <label class="form-label">Date</label>
            <InputDate class="form-control" @bind-Value="Step2.Date" @bind:after="OnDateChanged" />
            <ValidationMessage For="() => Step2.Date" />
            @if (Step2.Date.HasValue && Step2.Date.Value <= DateOnly.FromDateTime(DateTime.Today))
            {
                <div class="text-danger">Date must be in the future.</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label">Time Slot</label>
            <InputSelect class="form-select" @bind-Value="Step2.TimeSlot" disabled="@(!timeSlots.Any())">
                <option value="">-- Select --</option>
                @foreach (var slot in timeSlots)
                {
                    <option value="@slot">@slot</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Step2.TimeSlot" />
        </div>

        <div class="mb-3">
            <label class="form-label">Reason for Visit</label>
            <InputTextArea class="form-control" @bind-Value="Step2.ReasonForVisit" rows="3" />
            <ValidationMessage For="() => Step2.ReasonForVisit" />
        </div>

        <button type="submit" class="btn btn-success" disabled="@isSubmitting">
            @(isSubmitting ? "Checking..." : "Check Availability")
        </button>
    </EditForm>
}

@if (isBooked)
{
    <div class="alert alert-success mt-4">
        Appointment booked successfully!
    </div>
}

@code {
    private AppointmentStep1Model Step1 { get; set; } = new();
    private AppointmentStep2Model Step2 { get; set; } = new();

    private EditContext? step2EditContext;
    private CustomValidator? customValidator;

    private bool showStep2;
    private bool isSubmitting;
    private bool isBooked;

    private List<string> doctors = new();
    private List<string> timeSlots = new();

    private async Task HandleStep1Submit()
    {
        showStep2 = true;
        doctors = await AppointmentService.GetDoctorsAsync();

        Step2 = new();
        step2EditContext = new EditContext(Step2);
        timeSlots = new();
        isBooked = false;
    }

    private async Task OnDateChanged()
    {
        if (Step2.Date.HasValue && Step2.Date.Value > DateOnly.FromDateTime(DateTime.Today)
            && !string.IsNullOrEmpty(Step2.Doctor))
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(Step2.Doctor, Step2.Date.Value);
        }
        else
        {
            timeSlots = new();
        }
        Step2.TimeSlot = null;
    }

    private async Task HandleStep2Submit()
    {
        customValidator?.ClearErrors();

        if (!step2EditContext!.Validate())
            return;

        // Client-side future-date check
        if (Step2.Date!.Value <= DateOnly.FromDateTime(DateTime.Today))
            return;

        isSubmitting = true;
        try
        {
            var errors = await AppointmentService.ValidatePatientAsync(
                Step1.Email!, Step1.InsuranceProvider!, Step2.Doctor!, Step2.TimeSlot!);

            if (errors.Count > 0)
            {
                customValidator!.DisplayErrors(errors);
                return;
            }

            isBooked = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

